476	  const commonObjectIds = Object.keys(previous.objectRects).filter((id) => next.objectRects[id]);
477	  if (commonObjectIds.length < 2) return { commonObjects: commonObjectIds.length, relativeOrderRetention: 1, meanDisplacement: 0 };
