480	    const rightRect = previous.objectRects[right];
481	    return previous.orientation === "DOWN" ? leftRect.x - rightRect.x : leftRect.y - rightRect.y;
482	  });
483	  const nextOrder = new Map([...commonObjectIds].sort((left, right) => {
484	    const leftRect = next.objectRects[left];
485	    const rightRect = next.objectRects[right];
486	    return next.orientation === "DOWN" ? leftRect.x - rightRect.x : leftRect.y - rightRect.y;
487	  }).map((id, index) => [id, index]));
488	  let inversions = 0;
489	  let pairs = 0;
490	  for (let leftIndex = 0; leftIndex < previousOrder.length; leftIndex += 1) {
491	    for (let rightIndex = leftIndex + 1; rightIndex < previousOrder.length; rightIndex += 1) {
492	      pairs += 1;
493	      if ((nextOrder.get(previousOrder[leftIndex]) ?? 0) > (nextOrder.get(previousOrder[rightIndex]) ?? 0)) inversions += 1;
494	    }
495	  }
496	  const anchorId = commonObjectIds[0];
497	  const anchorDelta = {
498	    x: next.objectRects[anchorId].x - previous.objectRects[anchorId].x,
499	    y: next.objectRects[anchorId].y - previous.objectRects[anchorId].y,
500	  };
