1	import { indexSemanticGraph, type SemanticGraph } from "./semantic-graph";
2	
3	export type CanvasMode = "browse" | "inspect" | "focus" | "trace";
4	
5	export type SemanticZoomLevel = "landscape" | "architecture" | "component" | "operational";
6	
7	export type CanvasSelection =
8	  | { kind: "object"; id: string }
9	  | { kind: "relationship"; id: string }
10	  | { kind: "flow"; id: string }
11	  | null;
12	
13	export type ObjectEmphasis = "primary" | "related" | "context" | "normal" | "muted";
14	
15	export type RelationshipEmphasis = "active" | "related" | "normal" | "muted" | "suppressed";
16	
17	export type RegionEmphasis = "active" | "normal" | "muted";
18	
19	export type CanvasInteractionState = {
20	  mode: CanvasMode;
21	  selection: CanvasSelection;
22	  activeFlowId: string | null;
23	  zoom: number;
24	  searchQuery: string;
25	};
26	
27	export type CanvasViewModel = {
28	  mode: CanvasMode;
29	  selection: CanvasSelection;
30	  activeFlowId: string | null;
31	  zoom: number;
32	  zoomLevel: SemanticZoomLevel;
33	  objectEmphasis: Map<string, ObjectEmphasis>;
34	  relationshipEmphasis: Map<string, RelationshipEmphasis>;
35	  regionEmphasis: Map<string, RegionEmphasis>;
36	  searchMatches: Set<string>;
37	  focusObjectIds: Set<string>;
38	  activeRelationshipIds: Set<string>;
39	};
40	
41	export function semanticZoomLevel(zoom: number): SemanticZoomLevel {
42	  if (zoom < 0.48) return "landscape";
43	  if (zoom < 0.8) return "architecture";
44	  if (zoom < 1.22) return "component";
45	  return "operational";
46	}
47	
48	function adjacentObjectId(sourceObjectId: string, targetObjectId: string, objectId: string) {
49	  return sourceObjectId === objectId ? targetObjectId : sourceObjectId;
50	}
51	
52	function neighbors(graph: SemanticGraph, objectIds: Set<string>) {
53	  const result = new Set<string>();
54	  for (const relationship of graph.relationships) {
55	    if (objectIds.has(relationship.sourceObjectId)) result.add(relationship.targetObjectId);
56	    if (objectIds.has(relationship.targetObjectId)) result.add(relationship.sourceObjectId);
57	  }
58	  return result;
59	}
60	
61	export function deriveCanvasView(graph: SemanticGraph, interaction: CanvasInteractionState): CanvasViewModel {
62	  const index = indexSemanticGraph(graph);
63	  const objectEmphasis = new Map(graph.objects.map((object) => [object.id, "normal" as ObjectEmphasis]));
64	  const relationshipEmphasis = new Map(graph.relationships.map((relationship) => [relationship.id, "normal" as RelationshipEmphasis]));
65	  const regionEmphasis = new Map(graph.regions.map((region) => [region.id, "normal" as RegionEmphasis]));
66	  const focusObjectIds = new Set<string>();
67	  const activeRelationshipIds = new Set<string>();
68	  const query = interaction.searchQuery.trim().toLowerCase();
69	  const searchMatches = new Set(
