"""Minimal MCP stdio client for the prax-mcp server.

Usage: python prax_call.py <tool_name> <arguments_json> [--timeout seconds]

Bypasses harness-side argument validation by speaking MCP directly.
Prints the tool result JSON to stdout.
"""
import json
import shutil
import subprocess
import sys
import threading
import queue
import os

IN_FILE = os.path.join(os.path.dirname(__file__), "prax_session.json")


def main():
    tool = sys.argv[1]
    args = json.loads(sys.argv[2]) if len(sys.argv) > 2 else {}
    timeout = 60
    if "--timeout" in sys.argv:
        timeout = int(sys.argv[sys.argv.index("--timeout") + 1])

    exe = shutil.which("prax-mcp") or shutil.which("prax-mcp.cmd")
    if exe is None:
        print(json.dumps({"error": "prax-mcp not found on PATH"}))
        return 1
    if exe.endswith(".cmd") or exe.endswith(".bat"):
        exe = [shutil.which("cmd"), "/c", exe]
    else:
        exe = [exe]

    proc = subprocess.Popen(exe, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, encoding="utf-8")
    out_q: "queue.Queue[str]" = queue.Queue()

    def reader():
        for line in proc.stdout:
            out_q.put(line)

    threading.Thread(target=reader, daemon=True).start()

    pending = {}

    def request(req_id, method, params):
        pending[req_id] = method
        proc.stdin.write(json.dumps({"jsonrpc": "2.0", "id": req_id, "method": method, "params": params}) + "\n")
        proc.stdin.flush()

    def notify(method, params):
        proc.stdin.write(json.dumps({"jsonrpc": "2.0", "method": method, "params": params}) + "\n")
        proc.stdin.flush()

    def wait_for(req_id):
        import time
        deadline = time.time() + timeout
        while time.time() < deadline:
            try:
                line = out_q.get(timeout=1)
            except queue.Empty:
                continue
            try:
                message = json.loads(line)
            except json.JSONDecodeError:
                continue
            if message.get("id") == req_id:
                return message
        return {"error": f"timeout waiting for response {req_id}"}

    request(1, "initialize", {
        "protocolVersion": "2024-11-05",
        "capabilities": {},
        "clientInfo": {"name": "ecp-prax-cli", "version": "0.1"},
    })
    init = wait_for(1)
    if "error" in init:
        print(json.dumps(init, ensure_ascii=False))
        return 1
    notify("notifications/initialized", {})
    request(2, "tools/call", {"name": tool, "arguments": args})
    result = wait_for(2)
    proc.stdin.close()
    proc.terminate()

    content = result.get("result", {}).get("content", [])
    for item in content:
        if item.get("type") == "text":
            text = item.get("text", "")
            try:
                parsed = json.loads(text)
                print(json.dumps(parsed, ensure_ascii=False, indent=2))
            except json.JSONDecodeError:
                print(text)
        else:
            print(json.dumps(item, ensure_ascii=False))
    if result.get("isError") or "error" in result:
        print(json.dumps(result.get("error", {"isError": True}), ensure_ascii=False))
    session_id = None
    try:
        body = json.loads("".join(i.get("text", "") for i in content)) if content else {}
        session_id = body.get("design_session_id") or body.get("session_id")
    except Exception:
        pass
    if session_id:
        with open(IN_FILE, "w", encoding="utf-8") as f:
            json.dump({"design_session_id": session_id}, f)
        print(f"\n[session saved: {session_id}]", file=sys.stderr)
    return 0


if __name__ == "__main__":
    sys.exit(main())

