import {
  SEMANTIC_GRAPH_VERSION,
  type SemanticFlow,
  type SemanticGraph,
  type SemanticObject,
  type SemanticObjectType,
  type SemanticRegion,
  type SemanticRelationship,
  type SemanticRelationshipType,
  type SemanticState,
} from "./semantic-graph";

export type CanvasFixtureName = "small" | "medium" | "large" | "complex";

const confirmedState: SemanticState = {
  value: "confirmed",
  label: "Confirmed",
  severity: "positive",
  source: "knowledge",
};

const attentionState: SemanticState = {
  value: "attention",
  label: "Needs evidence",
  severity: "attention",
  source: "knowledge",
};

const OBJECT_TYPES: SemanticObjectType[] = ["service", "service", "agent", "storage", "service", "external"];
const RELATIONSHIP_TYPES: SemanticRelationshipType[] = ["data", "control", "event", "dependency", "external"];

const NAME_PARTS = [
  "Ingress", "Identity", "Intent", "Context", "Planner", "Policy", "Execution", "Registry", "Evidence", "Revision",
  "Runtime", "Telemetry", "Artifact", "Knowledge", "Delivery", "Coordinator", "Reconciler", "Observation", "Gateway", "Index",
];

function pad(value: number) {
  return String(value).padStart(3, "0");
}

function makeRegions(name: CanvasFixtureName, count: number, nested: boolean): SemanticRegion[] {
  const rootId = `${name}:region:system`;
  const regions: SemanticRegion[] = [{
    id: rootId,
    name: `${name[0].toUpperCase()}${name.slice(1)} System`,
    summary: "Fixture system boundary",
    importance: { level: "critical", score: 95 },
    order: 0,
    metadata: { fixture: name, root: true },
  }];
  for (let index = 1; index < count; index += 1) {
    const parentRegionId = nested && index >= count - 2 ? `${name}:region:${pad(((index - 1) % Math.max(1, count - 3)) + 1)}` : rootId;
    regions.push({
      id: `${name}:region:${pad(index)}`,
      name: index % 2 === 0 ? `Domain ${index} · Runtime Plane` : `Domain ${index} · Control Plane`,
      summary: index >= count - 2 && nested ? "Nested operational boundary" : "Primary system domain",
      parentRegionId,
      importance: { level: index < 3 ? "high" : "normal", score: Math.max(38, 82 - index * 5) },
      order: index,
      metadata: { fixture: name, nested: parentRegionId !== rootId },
    });
  }
  return regions;
}

function makeObject(name: CanvasFixtureName, index: number, regionIds: string[], longLabels: boolean): SemanticObject {
  const objectType = OBJECT_TYPES[index % OBJECT_TYPES.length];
  const baseName = `${NAME_PARTS[index % NAME_PARTS.length]} ${objectType === "storage" ? "Store" : objectType === "agent" ? "Agent" : objectType === "external" ? "Provider" : "Service"}`;
  const objectName = longLabels && index % 11 === 0
    ? `${baseName} for Revision-Pinned Architecture Observation Reconciliation`
    : `${baseName} ${pad(index + 1)}`;
  return {
    id: `${name}:object:${pad(index)}`,
    name: objectName,
    summary: index % 9 === 0
      ? "Coordinates validated system facts across region boundaries while preserving revision identity and human-readable evidence."
      : `Owns ${NAME_PARTS[(index + 3) % NAME_PARTS.length].toLowerCase()} responsibilities in the fixture architecture.`,
    objectType,
    regionId: regionIds[index % regionIds.length],
    state: index % 17 === 0 ? attentionState : confirmedState,
    importance: index < 2
      ? { level: "critical", score: 94 - index }
      : index < 8
        ? { level: "high", score: 78 - index }
        : { level: index % 13 === 0 ? "low" : "normal", score: index % 13 === 0 ? 28 : 52 },
    metadata: {
      fixture: name,
      technology: objectType === "storage" ? "Durable state" : objectType === "agent" ? "Agent runtime" : objectType === "external" ? "External API" : "TypeScript service",
      canonicalEntityType: objectType,
      repositoryRefs: [`repo://fixture/${name}/${pad(index)}`],
    },
    layoutHints: { order: index },
  };
}

function portHints(type: SemanticRelationshipType) {
  if (type === "event") return { sourcePortRole: "event" as const, targetPortRole: "event" as const, sourcePortSide: "bottom" as const, targetPortSide: "top" as const };
  if (type === "dependency") return { sourcePortRole: "downstream" as const, targetPortRole: "upstream" as const, sourcePortSide: "bottom" as const, targetPortSide: "top" as const };
  return { sourcePortRole: type === "control" ? "control" as const : "output" as const, targetPortRole: type === "control" ? "control" as const : "input" as const, sourcePortSide: "right" as const, targetPortSide: "left" as const };
}

function makeRelationships(name: CanvasFixtureName, objectCount: number, relationshipCount: number, isolatedLastObject: boolean) {
  const relationships: SemanticRelationship[] = [];
  const endpointIds = new Map<string, string>();
  const connectedCount = isolatedLastObject ? objectCount - 1 : objectCount;

  const add = (sourceIndex: number, targetIndex: number, typeIndex: number) => {
    if (sourceIndex === targetIndex || relationships.length >= relationshipCount) return;
    const key = `${sourceIndex}:${targetIndex}`;
    if (endpointIds.has(key)) return;
    const type = RELATIONSHIP_TYPES[typeIndex % RELATIONSHIP_TYPES.length];
    const id = `${name}:relationship:${pad(relationships.length)}`;
    relationships.push({
      id,
      sourceObjectId: `${name}:object:${pad(sourceIndex)}`,
      targetObjectId: `${name}:object:${pad(targetIndex)}`,
      relationshipType: type,
      direction: "directed",
      label: type === "data" ? "validated payload" : type === "control" ? "invokes" : type === "event" ? "state changed" : type === "dependency" ? "requires" : "external contract",
      summary: `Deterministic ${type} relationship from object ${sourceIndex} to object ${targetIndex}.`,
      state: relationships.length % 29 === 0 ? attentionState : confirmedState,
      importance: { level: relationships.length < 8 ? "high" : "normal", score: relationships.length < 8 ? 72 : 50 },
      metadata: { fixture: name, flowIds: [] as string[] },
      layoutHints: { ...portHints(type), order: relationships.length },
    });
    endpointIds.set(key, id);
  };

  for (let index = 0; index < connectedCount - 1; index += 1) add(index, index + 1, index);
  for (let index = 2; index < Math.min(connectedCount, 18); index += 1) add(0, index, index + 1);
  for (let index = 3; index < Math.min(connectedCount, 20); index += 1) add(index, 1, index + 2);
  for (let offset = 2; relationships.length < relationshipCount && offset < connectedCount; offset += 1) {
    for (let source = 0; source < connectedCount && relationships.length < relationshipCount; source += 1) {
      const target = (source + offset + (source % 3)) % connectedCount;
      add(source, target, source + offset);
    }
  }
  if (relationships.length !== relationshipCount) throw new Error(`Could not build ${name} fixture relationship budget`);
  return { relationships, endpointIds };
}

function makeFlow(
  name: CanvasFixtureName,
  flowIndex: number,
  objectIndexes: number[],
  endpointIds: Map<string, string>,
): SemanticFlow {
  const flowId = `${name}:flow:${flowIndex + 1}`;
  const objectIds = objectIndexes.map((index) => `${name}:object:${pad(index)}`);
  const relationshipIds = objectIndexes.slice(0, -1)
    .map((sourceIndex, index) => endpointIds.get(`${sourceIndex}:${objectIndexes[index + 1]}`))
    .filter((id): id is string => Boolean(id));
  const steps = objectIndexes.map((objectIndex, index) => ({
    id: `${flowId}:step:${index + 1}`,
    objectId: `${name}:object:${pad(objectIndex)}`,
    sequence: index + 1,
    role: index === 0 ? "entry" : index === objectIndexes.length - 1 ? "exit" : index % 3 === 0 ? "guard" : "transformer",
    title: index === 0 ? "Accept intent" : index === objectIndexes.length - 1 ? "Publish evidence" : `Transform stage ${index + 1}`,
    inputs: index === 0 ? ["user intent"] : [`stage ${index} output`],
    action: index % 3 === 0 ? "Validate revision and policy constraints" : "Transform the declared semantic payload",
    outputs: index === objectIndexes.length - 1 ? ["verified outcome"] : [`stage ${index + 1} output`],
    stateReads: index % 2 === 0 ? ["revision context"] : [],
    stateWrites: index % 3 === 0 ? ["evidence trail"] : [],
    failureModes: index % 4 === 0 ? ["stale revision", "missing evidence"] : [],
    nextStepIds: index < objectIndexes.length - 1 ? [`${flowId}:step:${index + 2}`] : [],
    metadata: { fixture: name },
  }));
  return {
    id: flowId,
    name: flowIndex === 0 ? "Intent to Verified Change" : flowIndex === 1 ? "Observation to Runtime Context" : "Evidence Reconciliation",
    description: "A bounded learning slice over the shared Semantic Graph.",
    objectIds,
    relationshipIds,
    steps,
    state: confirmedState,
    importance: { level: "high", score: 82 - flowIndex * 3 },
    metadata: { fixture: name, trigger: "Declared input", outcome: "Verified system fact" },
  };
}

function buildFixture(
  name: CanvasFixtureName,
  objectCount: number,
  relationshipCount: number,
  regionCount: number,
  options: { nested?: boolean; longLabels?: boolean; isolated?: boolean; flowCount?: number } = {},
): SemanticGraph {
  const regions = makeRegions(name, regionCount, Boolean(options.nested));
  const leafRegionIds = regions.filter((candidate) => !regions.some((region) => region.parentRegionId === candidate.id)).map((region) => region.id);
  const objects = Array.from({ length: objectCount }, (_, index) => makeObject(name, index, leafRegionIds, Boolean(options.longLabels)));
  const { relationships, endpointIds } = makeRelationships(name, objectCount, relationshipCount, Boolean(options.isolated));
  const flowStarts = [0, Math.min(12, objectCount - 9), Math.min(24, objectCount - 8)];
  const flows = Array.from({ length: options.flowCount ?? 2 }, (_, index) => {
    const start = Math.max(0, flowStarts[index]);
    const length = Math.min(index === 0 ? 8 : 7, objectCount - start - (options.isolated ? 1 : 0));
    return makeFlow(name, index, Array.from({ length }, (__, step) => start + step), endpointIds);
  });
  for (const flow of flows) {
    for (const relationshipId of flow.relationshipIds) {
      const relationship = relationships.find((candidate) => candidate.id === relationshipId);
      const flowIds = relationship?.metadata.flowIds as string[] | undefined;
      if (flowIds && !flowIds.includes(flow.id)) flowIds.push(flow.id);
    }
  }
  return {
    id: `fixture:${name}`,
    version: SEMANTIC_GRAPH_VERSION,
    name: `${name[0].toUpperCase()}${name.slice(1)} Canvas Fixture`,
    regions,
    objects,
    relationships,
    flows,
    scope: {
      projectId: `canvas-fixture-${name}`,
      revision: 1,
      kind: "project",
      rootRegionId: regions[0].id,
      source: "fixture",
    },
    metadata: {
      fixture: name,
      expectedObjectCount: objectCount,
      expectedRelationshipCount: relationshipCount,
      cases: options,
    },
  };
}

export const SMALL_CANVAS_FIXTURE = buildFixture("small", 15, 20, 4, { flowCount: 2 });
export const MEDIUM_CANVAS_FIXTURE = buildFixture("medium", 40, 70, 6, { nested: true, flowCount: 3 });
export const LARGE_CANVAS_FIXTURE = buildFixture("large", 100, 180, 10, { nested: true, flowCount: 3 });
export const COMPLEX_CANVAS_FIXTURE = buildFixture("complex", 64, 124, 9, {
  nested: true,
  longLabels: true,
  isolated: true,
  flowCount: 3,
});

export const CANVAS_FIXTURES: Record<CanvasFixtureName, SemanticGraph> = {
  small: SMALL_CANVAS_FIXTURE,
  medium: MEDIUM_CANVAS_FIXTURE,
  large: LARGE_CANVAS_FIXTURE,
  complex: COMPLEX_CANVAS_FIXTURE,
};

