import ELK from "elkjs/lib/elk.bundled.js";
import {
  semanticGraphFingerprint,
  type SemanticGraph,
  type SemanticObject,
  type SemanticPortSide,
  type SemanticRegion,
  type SemanticRelationship,
} from "./semantic-graph";

const elk = new ELK();

export type LayoutOrientation = "RIGHT" | "DOWN";

export type LayoutRect = {
  id: string;
  x: number;
  y: number;
  width: number;
  height: number;
};

export type RegionLayoutRect = LayoutRect & {
  depth: number;
  parentRegionId?: string;
};

export type RelationshipRoute = {
  id: string;
  points: Array<{ x: number; y: number }>;
  labelPoint?: { x: number; y: number };
  sourceSide: SemanticPortSide;
  targetSide: SemanticPortSide;
};

export type CanvasLayout = {
  graphId: string;
  fingerprint: string;
  orientation: LayoutOrientation;
  width: number;
  height: number;
  durationMs: number;
  objectRects: Record<string, LayoutRect>;
  regionRects: Record<string, RegionLayoutRect>;
  relationshipRoutes: Record<string, RelationshipRoute>;
};

// A parent region with at least this many child Regions is composed as a 2D grid
// instead of one ELK-directed band, so top-level structure uses both screen axes.
const GRID_SPLIT_MIN_SIBLINGS = 3;
const GRID_GAP_X = 150;
const GRID_GAP_Y = 130;
const GRID_TARGET_ASPECT = 1.7;
const CONTAINER_PADDING = { top: 58, left: 28, bottom: 28, right: 28 };

function intersects(left: LayoutRect, right: LayoutRect, padding = 22) {
  return left.x < right.x + right.width + padding
    && left.x + left.width + padding > right.x
    && left.y < right.y + right.height + padding
    && left.y + left.height + padding > right.y;
}

function stabilizeIncrementalLayout(graph: SemanticGraph, previous: CanvasLayout, next: CanvasLayout): CanvasLayout {
  if (previous.fingerprint === next.fingerprint) return { ...previous, durationMs: 0 };
  const graphObjectIds = new Set(graph.objects.map((object) => object.id));
  const commonObjectIds = Object.keys(previous.objectRects).filter((id) => graphObjectIds.has(id) && next.objectRects[id]);
  const priorObjectCount = Object.keys(previous.objectRects).length;
  if (priorObjectCount === 0 || commonObjectIds.length / priorObjectCount < .8) return next;

  const objectRects: Record<string, LayoutRect> = {};
  for (const id of commonObjectIds) {
    const prior = previous.objectRects[id];
    const measured = next.objectRects[id];
    objectRects[id] = { ...measured, x: prior.x, y: prior.y };
  }

  const additionsByRegion = new Map<string, number>();
  for (const object of graph.objects) {
    if (objectRects[object.id]) continue;
    const measured = next.objectRects[object.id];
    if (!measured) continue;
    const previousRegion = previous.regionRects[object.regionId];
    const nextRegion = next.regionRects[object.regionId];
    let candidate = previousRegion && nextRegion
      ? { ...measured, x: previousRegion.x + measured.x - nextRegion.x, y: previousRegion.y + measured.y - nextRegion.y }
      : measured;
    if (Object.values(objectRects).some((rect) => intersects(candidate, rect))) {
      const additionIndex = additionsByRegion.get(object.regionId) ?? 0;
      additionsByRegion.set(object.regionId, additionIndex + 1);
      const anchor = previousRegion ?? nextRegion;
      candidate = {
        ...measured,
        x: (anchor?.x ?? 0) + (anchor?.width ?? 0) + 52,
        y: (anchor?.y ?? 0) + 54 + additionIndex * (measured.height + 28),
      };
    }
    objectRects[object.id] = candidate;
  }

  const regionRects: Record<string, RegionLayoutRect> = {};
  for (const region of graph.regions) {
    regionRects[region.id] = previous.regionRects[region.id] ?? next.regionRects[region.id];
  }
  for (const object of graph.objects) {
    const objectRect = objectRects[object.id];
    const regionRect = regionRects[object.regionId];
    if (!objectRect || !regionRect) continue;
    const right = Math.max(regionRect.x + regionRect.width, objectRect.x + objectRect.width + 26);
    const bottom = Math.max(regionRect.y + regionRect.height, objectRect.y + objectRect.height + 26);
    regionRects[object.regionId] = { ...regionRect, width: right - regionRect.x, height: bottom - regionRect.y };
  }

  const relationshipRoutes: Record<string, RelationshipRoute> = {};
  for (const relationship of graph.relationships) {
    const previousRoute = previous.relationshipRoutes[relationship.id];
    const sourcePrevious = previous.objectRects[relationship.sourceObjectId];
    const targetPrevious = previous.objectRects[relationship.targetObjectId];
    const sourceNext = objectRects[relationship.sourceObjectId];
    const targetNext = objectRects[relationship.targetObjectId];
    const geometryUnchanged = sourcePrevious && targetPrevious && sourceNext && targetNext
      && sourcePrevious.x === sourceNext.x && sourcePrevious.y === sourceNext.y
      && sourcePrevious.width === sourceNext.width && sourcePrevious.height === sourceNext.height
      && targetPrevious.x === targetNext.x && targetPrevious.y === targetNext.y
      && targetPrevious.width === targetNext.width && targetPrevious.height === targetNext.height;
    if (previousRoute && geometryUnchanged) relationshipRoutes[relationship.id] = previousRoute;
  }

  const allRects = [...Object.values(objectRects), ...Object.values(regionRects)];
  const width = Math.max(next.width, ...allRects.map((rect) => rect.x + rect.width + 42));
  const height = Math.max(next.height, ...allRects.map((rect) => rect.y + rect.height + 42));
  return { ...next, width, height, objectRects, regionRects, relationshipRoutes };
}

type ElkPoint = { x?: number; y?: number };

type ElkPort = {
  id: string;
  width: number;
  height: number;
  layoutOptions: Record<string, string>;
};

type ElkLabel = { id: string; text?: string; width: number; height: number; x?: number; y?: number };

type ElkSection = { startPoint?: ElkPoint; bendPoints?: ElkPoint[]; endPoint?: ElkPoint };

type ElkEdge = {
  id: string;
  sources?: string[];
  targets?: string[];
  labels?: ElkLabel[];
  sections?: ElkSection[];
  container?: string;
};

type ElkNode = {
  id: string;
  x?: number;
  y?: number;
  width?: number;
  height?: number;
  children?: ElkNode[];
  ports?: ElkPort[];
  edges?: ElkEdge[];
  layoutOptions?: Record<string, string>;
};

type PortSpec = { id: string; side: SemanticPortSide; order: number };

const SIDE_TO_ELK: Record<SemanticPortSide, string> = {
  left: "WEST",
  right: "EAST",
  top: "NORTH",
  bottom: "SOUTH",
};

function textUnits(value: string) {
  return [...value].reduce((total, character) => total + (/[^�-ÿ]/.test(character) ? 1.75 : 1), 0);
}

function objectSize(name: string, summary = "") {
  const nameUnits = textUnits(name);
  const width = Math.max(232, Math.min(296, 212 + Math.max(0, nameUnits - 14) * 4.2));
  const height = nameUnits > 26 || textUnits(summary) > 90 ? 144 : 124;
  return { width: Math.round(width), height };
}

function edgeLabelSize(label: string) {
  const units = textUnits(label);
  return {
    width: Math.max(42, Math.min(168, Math.round(units * 7.1 + 18))),
    height: units > 22 ? 34 : 20,
  };
}

function routeMidpoint(points: Array<{ x: number; y: number }>) {
  if (points.length < 2) return undefined;
  const segments = points.slice(0, -1).map((start, index) => ({
    start,
    end: points[index + 1],
    length: Math.abs(points[index + 1].x - start.x) + Math.abs(points[index + 1].y - start.y),
  }));
  const total = segments.reduce((sum, segment) => sum + segment.length, 0);
  let remaining = total / 2;
  for (const segment of segments) {
    if (remaining > segment.length) {
      remaining -= segment.length;
      continue;
    }
    const ratio = segment.length === 0 ? 0 : remaining / segment.length;
    return {
      x: segment.start.x + (segment.end.x - segment.start.x) * ratio,
      y: segment.start.y + (segment.end.y - segment.start.y) * ratio,
    };
  }
  return points[Math.floor(points.length / 2)];
}

function rotateSide(side: SemanticPortSide | undefined, fallback: SemanticPortSide, orientation: LayoutOrientation): SemanticPortSide {
  const resolved = side ?? fallback;
  if (orientation === "RIGHT") return resolved;
  if (resolved === "left") return "top";
  if (resolved === "right") return "bottom";
  if (resolved === "top") return "left";
  return "right";
}

function routeSides(relationship: SemanticRelationship, orientation: LayoutOrientation) {
  return {
    sourceSide: rotateSide(relationship.layoutHints?.sourcePortSide, "right", orientation),
    targetSide: rotateSide(relationship.layoutHints?.targetPortSide, "left", orientation),
  };
}

function stableObjectOrder(graph: SemanticGraph, previous?: CanvasLayout) {
  const result = new Map<string, number>();
  const byRegion = new Map<string, SemanticObject[]>();
  for (const object of graph.objects) byRegion.set(object.regionId, [...(byRegion.get(object.regionId) ?? []), object]);
  for (const objects of byRegion.values()) {
    objects.sort((left, right) => {
      const leftRect = previous?.objectRects[left.id];
      const rightRect = previous?.objectRects[right.id];
      if (leftRect && rightRect) {
        const primary = previous?.orientation === "DOWN" ? leftRect.x - rightRect.x : leftRect.y - rightRect.y;
        if (primary !== 0) return primary;
      }
      if (leftRect && !rightRect) return -1;
      if (!leftRect && rightRect) return 1;
      return (left.layoutHints?.order ?? 0) - (right.layoutHints?.order ?? 0) || left.id.localeCompare(right.id);
    });
    objects.forEach((object, index) => result.set(object.id, index));
  }
  return result;
}

function buildPortSpecs(relationships: SemanticRelationship[], orientation: LayoutOrientation) {
  const portsByObject = new Map<string, PortSpec[]>();
  const relationshipPorts = new Map<string, { sourcePortId: string; targetPortId: string; sourceSide: SemanticPortSide; targetSide: SemanticPortSide }>();
  const orderedRelationships = [...relationships].sort((left, right) =>
    (left.layoutHints?.order ?? 0) - (right.layoutHints?.order ?? 0) || left.id.localeCompare(right.id));
  const sideCounts = new Map<string, number>();

  for (const relationship of orderedRelationships) {
    const { sourceSide, targetSide } = routeSides(relationship, orientation);
    const sourceKey = `${relationship.sourceObjectId}:${sourceSide}`;
    const targetKey = `${relationship.targetObjectId}:${targetSide}`;
    const sourceOrder = sideCounts.get(sourceKey) ?? 0;
    const targetOrder = sideCounts.get(targetKey) ?? 0;
    sideCounts.set(sourceKey, sourceOrder + 1);
    sideCounts.set(targetKey, targetOrder + 1);
    const sourcePortId = `${relationship.id}:source-port`;
    const targetPortId = `${relationship.id}:target-port`;
    portsByObject.set(relationship.sourceObjectId, [
      ...(portsByObject.get(relationship.sourceObjectId) ?? []),
      { id: sourcePortId, side: sourceSide, order: sourceOrder },
    ]);
    portsByObject.set(relationship.targetObjectId, [
      ...(portsByObject.get(relationship.targetObjectId) ?? []),
      { id: targetPortId, side: targetSide, order: targetOrder },
    ]);
    relationshipPorts.set(relationship.id, { sourcePortId, targetPortId, sourceSide, targetSide });
  }
  return { portsByObject, relationshipPorts };
}

function regionDepth(region: SemanticRegion, regionById: Map<string, SemanticRegion>) {
  let depth = 0;
  let cursor = region.parentRegionId ? regionById.get(region.parentRegionId) : undefined;
  const seen = new Set<string>();
  while (cursor && !seen.has(cursor.id)) {
    depth += 1;
    seen.add(cursor.id);
    cursor = cursor.parentRegionId ? regionById.get(cursor.parentRegionId) : undefined;
  }
  return depth;
}

function asElkPort(port: PortSpec): ElkPort {
  return {
    id: port.id,
    width: 2,
    height: 2,
    layoutOptions: {
      "elk.port.side": SIDE_TO_ELK[port.side],
      "elk.port.index": String(port.order),
    },
  };
}

function regionOptions(orientation: LayoutOrientation, depth: number) {
  return {
    "elk.algorithm": "layered",
    "elk.direction": orientation,
    "elk.edgeRouting": "ORTHOGONAL",
    "elk.padding": `[top=${depth === 0 ? 54 : 46},left=26,bottom=26,right=26]`,
    "elk.spacing.nodeNode": depth === 0 ? "34" : "28",
    "elk.layered.spacing.nodeNodeBetweenLayers": depth === 0 ? "82" : "68",
    "elk.layered.spacing.edgeNodeBetweenLayers": "30",
    "elk.layered.spacing.edgeEdgeBetweenLayers": "16",
    "elk.layered.nodePlacement.strategy": "NETWORK_SIMPLEX",
    "elk.layered.crossingMinimization.strategy": "LAYER_SWEEP",
    "elk.layered.crossingMinimization.greedySwitch.type": "TWO_SIDED",
  };
}

type LayoutBlock = {
  width: number;
  height: number;
  objectRects: Record<string, LayoutRect>;
  regionRects: Record<string, RegionLayoutRect>;
  relationshipRoutes: Record<string, RelationshipRoute>;
};

function translateBlock(block: LayoutBlock, dx: number, dy: number): LayoutBlock {
  return {
    width: block.width,
    height: block.height,
    objectRects: Object.fromEntries(Object.entries(block.objectRects).map(([id, rect]) => [id, { ...rect, x: rect.x + dx, y: rect.y + dy }])),
    regionRects: Object.fromEntries(Object.entries(block.regionRects).map(([id, rect]) => [id, { ...rect, x: rect.x + dx, y: rect.y + dy }])),
    relationshipRoutes: Object.fromEntries(Object.entries(block.relationshipRoutes).map(([id, route]) => [id, {
      ...route,
      points: route.points.map((point) => ({ x: point.x + dx, y: point.y + dy })),
      labelPoint: route.labelPoint ? { x: route.labelPoint.x + dx, y: route.labelPoint.y + dy } : undefined,
    }])),
  };
}

type GridPlacement = { positions: Map<string, { x: number; y: number }>; width: number; height: number };

// Packs sibling Region blocks row-major into a grid whose aspect approaches the
// viewport, replacing the single-axis band with a scannable 2D composition.
export function packRegionGrid(blocks: Array<{ id: string; width: number; height: number }>): GridPlacement {
  if (blocks.length === 0) return { positions: new Map(), width: 0, height: 0 };
  let best: { k: number; score: number } | null = null;
  for (let k = 1; k <= blocks.length; k += 1) {
    const rows: Array<Array<{ id: string; width: number; height: number }>> = [];
    for (let index = 0; index < blocks.length; index += k) rows.push(blocks.slice(index, index + k));
    const rowWidths = rows.map((row) => row.reduce((sum, block) => sum + block.width, 0) + GRID_GAP_X * (row.length - 1));
    const rowHeights = rows.map((row) => Math.max(...row.map((block) => block.height)));
    const width = Math.max(...rowWidths);
    const height = rowHeights.reduce((sum, rowHeight) => sum + rowHeight, 0) + GRID_GAP_Y * (rows.length - 1);
    const aspect = width / Math.max(height, 1);
    const fill = blocks.reduce((sum, block) => sum + block.width * block.height, 0) / Math.max(width * height, 1);
    const score = Math.abs(Math.log(aspect / GRID_TARGET_ASPECT)) + .35 * (1 - fill);
    if (!best || score < best.score - 1e-9 || (Math.abs(score - best.score) < 1e-9 && k > best.k)) best = { k, score };
  }
  const positions = new Map<string, { x: number; y: number }>();
  let cursorY = 0;
  let index = 0;
  let width = 0;
  let height = 0;
  while (index < blocks.length) {
    const row = blocks.slice(index, index + best!.k);
    const rowHeight = Math.max(...row.map((block) => block.height));
    let cursorX = 0;
    for (const block of row) {
      positions.set(block.id, { x: cursorX, y: cursorY });
      cursorX += block.width + GRID_GAP_X;
    }
    width = Math.max(width, cursorX - GRID_GAP_X);
    height = cursorY + rowHeight;
    cursorY += rowHeight + GRID_GAP_Y;
    index += row.length;
  }
  return { positions, width, height };
}

export async function layoutSemanticGraph(
  graph: SemanticGraph,
  options: { orientation?: LayoutOrientation; previousLayout?: CanvasLayout } = {},
): Promise<CanvasLayout> {
  const started = typeof performance === "undefined" ? Date.now() : performance.now();
  const fingerprint = semanticGraphFingerprint(graph);
  if (options.previousLayout?.fingerprint === fingerprint) return { ...options.previousLayout, graphId: graph.id, fingerprint, durationMs: 0 };
  const orientation = options.orientation ?? "RIGHT";
  const objectOrder = stableObjectOrder(graph, options.previousLayout);
  const regionById = new Map(graph.regions.map((region) => [region.id, region]));
  const objectsByRegion = new Map<string, SemanticObject[]>();
  const childRegions = new Map<string | null, SemanticRegion[]>();
  for (const object of graph.objects) objectsByRegion.set(object.regionId, [...(objectsByRegion.get(object.regionId) ?? []), object]);
  for (const region of graph.regions) childRegions.set(region.parentRegionId ?? null, [...(childRegions.get(region.parentRegionId ?? null) ?? []), region]);

  const subtreeRegions = (regionId: string): SemanticRegion[] => {
    const collected: SemanticRegion[] = [];
    const walk = (id: string) => {
      for (const child of childRegions.get(id) ?? []) {
        collected.push(child);
        walk(child.id);
      }
    };
    walk(regionId);
    return collected;
  };
  const subtreeRegionIds = (regionId: string) => new Set([regionId, ...subtreeRegions(regionId).map((region) => region.id)]);
  const scopeObjectIds = (regionIds: Set<string>) => new Set(graph.objects.filter((object) => regionIds.has(object.regionId)).map((object) => object.id));

  async function runElkScope(params: {
    runId: string;
    scopeRegionIds: Set<string>;
    rootRegions: SemanticRegion[];
    rootObjects: SemanticObject[];
  }): Promise<LayoutBlock> {
    const { runId, scopeRegionIds, rootRegions, rootObjects } = params;
    const scopeObjectSet = scopeObjectIds(scopeRegionIds);
    const scopedEdges = graph.relationships
      .filter((relationship) => scopeObjectSet.has(relationship.sourceObjectId) && scopeObjectSet.has(relationship.targetObjectId));
    const { portsByObject, relationshipPorts } = buildPortSpecs(scopedEdges, orientation);

    const buildObjectNode = (object: SemanticObject): ElkNode => {
      const size = objectSize(object.name, object.summary);
      return {
        id: object.id,
        width: size.width,
        height: size.height,
        ports: (portsByObject.get(object.id) ?? []).sort((left, right) => left.side.localeCompare(right.side) || left.order - right.order).map(asElkPort),
        layoutOptions: {
          "elk.portConstraints": "FIXED_ORDER",
          "elk.layered.priority.direction": String(Math.round(object.importance.score)),
        },
      };
    };
    const buildRegion = (region: SemanticRegion): ElkNode => {
      const depth = regionDepth(region, regionById);
      const nestedRegions = [...(childRegions.get(region.id) ?? [])]
        .sort((left, right) => (left.order ?? 0) - (right.order ?? 0) || left.id.localeCompare(right.id))
        .map(buildRegion);
      const objects = [...(objectsByRegion.get(region.id) ?? [])]
        .sort((left, right) => (objectOrder.get(left.id) ?? 0) - (objectOrder.get(right.id) ?? 0) || left.id.localeCompare(right.id))
        .map(buildObjectNode);
      return {
        id: region.id,
        children: [...nestedRegions, ...objects],
        layoutOptions: regionOptions(orientation, depth),
      };
    };

    const children = [...rootRegions.map(buildRegion), ...rootObjects.map(buildObjectNode)];
    const elkEdges: ElkEdge[] = scopedEdges.map((relationship) => {
      const ports = relationshipPorts.get(relationship.id);
      const label = relationship.label?.trim();
      const flowIds = Array.isArray(relationship.metadata.flowIds) ? relationship.metadata.flowIds : [];
      const includeLabelInLayout = graph.objects.length <= 60 || flowIds.length > 0;
      const labelSize = label && includeLabelInLayout ? edgeLabelSize(label) : null;
      return {
        id: relationship.id,
        sources: [ports?.sourcePortId ?? relationship.sourceObjectId],
        targets: [ports?.targetPortId ?? relationship.targetObjectId],
        labels: label && labelSize ? [{ id: `${relationship.id}:label`, text: label, ...labelSize }] : [],
      };
    });

    const output = await elk.layout({
      id: runId,
      layoutOptions: {
        ...regionOptions(orientation, -1),
        "elk.hierarchyHandling": "INCLUDE_CHILDREN",
        "elk.separateConnectedComponents": "false",
        "elk.spacing.componentComponent": "72",
        "elk.spacing.edgeNode": "28",
        "elk.spacing.labelNode": "18",
        "elk.spacing.edgeLabel": "12",
        "elk.edgeLabels.inline": "true",
        "elk.layered.unnecessaryBendpoints": "true",
        "elk.layered.thoroughness": graph.objects.length >= 80 ? "3" : "7",
        "elk.padding": "[top=42,left=42,bottom=42,right=42]",
      },
      children,
      edges: elkEdges,
    } as unknown as Parameters<typeof elk.layout>[0]) as unknown as ElkNode;

    const objectRects: Record<string, LayoutRect> = {};
    const regionRects: Record<string, RegionLayoutRect> = {};
    const absoluteOffsetById = new Map<string, { x: number; y: number }>([[runId, { x: 0, y: 0 }]]);

    const visit = (node: ElkNode, parentOffset: { x: number; y: number }) => {
      const x = parentOffset.x + (node.x ?? 0);
      const y = parentOffset.y + (node.y ?? 0);
      absoluteOffsetById.set(node.id, { x, y });
      if (scopeObjectSet.has(node.id)) objectRects[node.id] = { id: node.id, x, y, width: node.width ?? 0, height: node.height ?? 0 };
      if (scopeRegionIds.has(node.id)) {
        const region = regionById.get(node.id)!;
        regionRects[node.id] = {
          id: node.id,
          x,
          y,
          width: node.width ?? 0,
          height: node.height ?? 0,
          depth: regionDepth(region, regionById),
          parentRegionId: region.parentRegionId,
        };
      }
      for (const child of node.children ?? []) visit(child, { x, y });
    };
    visit(output, { x: 0, y: 0 });

    const outputEdges: ElkEdge[] = [];
    const collectEdges = (node: ElkNode) => {
      outputEdges.push(...(node.edges ?? []));
      for (const child of node.children ?? []) collectEdges(child);
    };
    collectEdges(output);

    const relationshipRoutes: Record<string, RelationshipRoute> = {};
    for (const edge of outputEdges) {
      const relationship = graph.relationships.find((candidate) => candidate.id === edge.id);
      if (!relationship) continue;
      const ports = relationshipPorts.get(edge.id);
      const offset = absoluteOffsetById.get(edge.container ?? runId) ?? { x: 0, y: 0 };
      const points: Array<{ x: number; y: number }> = [];
      for (const section of edge.sections ?? []) {
        const sectionPoints = [section.startPoint, ...(section.bendPoints ?? []), section.endPoint]
          .filter((point): point is ElkPoint => Boolean(point))
          .map((point) => ({ x: offset.x + (point.x ?? 0), y: offset.y + (point.y ?? 0) }));
        if (points.length > 0 && sectionPoints.length > 0) {
          const previous = points.at(-1)!;
          const next = sectionPoints[0];
          if (previous.x === next.x && previous.y === next.y) sectionPoints.shift();
        }
        points.push(...sectionPoints);
      }
      const label = edge.labels?.[0];
      relationshipRoutes[edge.id] = {
        id: edge.id,
        points,
        labelPoint: label
          ? { x: offset.x + (label.x ?? 0) + label.width / 2, y: offset.y + (label.y ?? 0) + label.height / 2 }
          : routeMidpoint(points),
        sourceSide: ports?.sourceSide ?? "right",
        targetSide: ports?.targetSide ?? "left",
      };
    }

    return {
      width: output.width ?? 0,
      height: output.height ?? 0,
      objectRects,
      regionRects,
      relationshipRoutes,
    };
  }

  async function layoutRegionSubtree(region: SemanticRegion): Promise<LayoutBlock> {
    const children = [...(childRegions.get(region.id) ?? [])]
      .sort((left, right) => (left.order ?? 0) - (right.order ?? 0) || left.id.localeCompare(right.id));
    if (children.length < GRID_SPLIT_MIN_SIBLINGS) {
      return runElkScope({ runId: `elk:${region.id}`, scopeRegionIds: subtreeRegionIds(region.id), rootRegions: [region], rootObjects: [] });
    }
    const directObjects = [...(objectsByRegion.get(region.id) ?? [])]
      .sort((left, right) => (objectOrder.get(left.id) ?? 0) - (objectOrder.get(right.id) ?? 0) || left.id.localeCompare(right.id));
    const blocks: Array<{ id: string; block: LayoutBlock }> = [];
    for (const child of children) {
      const block = await layoutRegionSubtree(child);
      blocks.push({ id: child.id, block });
    }
    if (directObjects.length > 0) {
      const block = await runElkScope({ runId: `elk:${region.id}:objects`, scopeRegionIds: new Set([region.id]), rootRegions: [], rootObjects: directObjects });
      blocks.push({ id: `${region.id}:objects`, block });
    }
    const { positions, width, height } = packRegionGrid(blocks.map(({ id, block }) => ({ id, width: block.width, height: block.height })));
    const merged: LayoutBlock = { width, height, objectRects: {}, regionRects: {}, relationshipRoutes: {} };
    for (const { id, block } of blocks) {
      const origin = positions.get(id)!;
      const translated = translateBlock(block, origin.x, origin.y);
      Object.assign(merged.objectRects, translated.objectRects);
      Object.assign(merged.regionRects, translated.regionRects);
      Object.assign(merged.relationshipRoutes, translated.relationshipRoutes);
    }
    merged.regionRects[region.id] = {
      id: region.id,
      x: -CONTAINER_PADDING.left,
      y: -CONTAINER_PADDING.top,
      width: width + CONTAINER_PADDING.left + CONTAINER_PADDING.right,
      height: height + CONTAINER_PADDING.top + CONTAINER_PADDING.bottom,
      depth: regionDepth(region, regionById),
      parentRegionId: region.parentRegionId,
    };
    const shifted = translateBlock(merged, CONTAINER_PADDING.left, CONTAINER_PADDING.top);
    return { ...shifted, regionRects: { ...shifted.regionRects, [region.id]: merged.regionRects[region.id] } };
  }

  const topLevelRegions = [...(childRegions.get(null) ?? [])]
    .sort((left, right) => (left.order ?? 0) - (right.order ?? 0) || left.id.localeCompare(right.id));
  let rootBlock: LayoutBlock;
  if (topLevelRegions.length >= GRID_SPLIT_MIN_SIBLINGS) {
    const blocks: Array<{ id: string; block: LayoutBlock }> = [];
    for (const region of topLevelRegions) {
      const block = await layoutRegionSubtree(region);
      blocks.push({ id: region.id, block });
    }
    const { positions, width, height } = packRegionGrid(blocks.map(({ id, block }) => ({ id, width: block.width, height: block.height })));
    rootBlock = { width, height, objectRects: {}, regionRects: {}, relationshipRoutes: {} };
    for (const { id, block } of blocks) {
      const origin = positions.get(id)!;
      const translated = translateBlock(block, origin.x, origin.y);
      Object.assign(rootBlock.objectRects, translated.objectRects);
      Object.assign(rootBlock.regionRects, translated.regionRects);
      Object.assign(rootBlock.relationshipRoutes, translated.relationshipRoutes);
    }
  } else {
    rootBlock = await runElkScope({
      runId: `elk:${graph.id}`,
      scopeRegionIds: new Set(graph.regions.map((region) => region.id)),
      rootRegions: topLevelRegions,
      rootObjects: [],
    });
  }

  const finished = typeof performance === "undefined" ? Date.now() : performance.now();
  const result: CanvasLayout = {
    graphId: graph.id,
    fingerprint,
    orientation,
    width: rootBlock.width,
    height: rootBlock.height,
    durationMs: Math.round((finished - started) * 100) / 100,
    objectRects: rootBlock.objectRects,
    regionRects: rootBlock.regionRects,
    relationshipRoutes: rootBlock.relationshipRoutes,
  };
  return options.previousLayout ? stabilizeIncrementalLayout(graph, options.previousLayout, result) : result;
}

export function measureLayoutStability(previous: CanvasLayout, next: CanvasLayout) {
  const commonObjectIds = Object.keys(previous.objectRects).filter((id) => next.objectRects[id]);
  if (commonObjectIds.length < 2) return { commonObjects: commonObjectIds.length, relativeOrderRetention: 1, meanDisplacement: 0 };
  const previousOrder = [...commonObjectIds].sort((left, right) => {
    const leftRect = previous.objectRects[left];
    const rightRect = previous.objectRects[right];
    return previous.orientation === "DOWN" ? leftRect.x - rightRect.x : leftRect.y - rightRect.y;
  });
  const nextOrder = new Map([...commonObjectIds].sort((left, right) => {
    const leftRect = next.objectRects[left];
    const rightRect = next.objectRects[right];
    return next.orientation === "DOWN" ? leftRect.x - rightRect.x : leftRect.y - rightRect.y;
  }).map((id, index) => [id, index]));
  let inversions = 0;
  let pairs = 0;
  for (let leftIndex = 0; leftIndex < previousOrder.length; leftIndex += 1) {
    for (let rightIndex = leftIndex + 1; rightIndex < previousOrder.length; rightIndex += 1) {
      pairs += 1;
      if ((nextOrder.get(previousOrder[leftIndex]) ?? 0) > (nextOrder.get(previousOrder[rightIndex]) ?? 0)) inversions += 1;
    }
  }
  const anchorId = commonObjectIds[0];
  const anchorDelta = {
    x: next.objectRects[anchorId].x - previous.objectRects[anchorId].x,
    y: next.objectRects[anchorId].y - previous.objectRects[anchorId].y,
  };
  const meanDisplacement = commonObjectIds.reduce((total, id) => {
    const previousRect = previous.objectRects[id];
    const nextRect = next.objectRects[id];
    return total + Math.hypot(nextRect.x - previousRect.x - anchorDelta.x, nextRect.y - previousRect.y - anchorDelta.y);
  }, 0) / commonObjectIds.length;
  return {
    commonObjects: commonObjectIds.length,
    relativeOrderRetention: pairs === 0 ? 1 : Math.round((1 - inversions / pairs) * 1000) / 1000,
    meanDisplacement: Math.round(meanDisplacement * 100) / 100,
  };
}

