"use client";

import type { CSSProperties } from "react";
import type { Node, NodeProps } from "@xyflow/react";
import { regionLabelScale } from "./camera";
import type { RegionNodeData } from "./types";

export type ArchitectureRegionNode = Node<RegionNodeData, "region">;

export default function RegionNode({ data }: NodeProps<ArchitectureRegionNode>) {
  const { region, emphasis, zoomLevel, zoom, objectCount, childRegionCount, subtreeObjectCount, keyObjectNames, depth } = data;
  const labelScale = regionLabelScale(zoom);
  return (
    <section
      aria-label={`Region ${region.name}`}
      className={`canvas-region depth-${Math.min(depth, 3)} emphasis-${emphasis} zoom-${zoomLevel}`}
      style={{ "--label-scale": labelScale } as CSSProperties}
    >
      <header>
        <span>Region</span>
        <strong>{region.name}</strong>
        <small>{subtreeObjectCount} objects{childRegionCount > 0 ? ` · ${childRegionCount} regions` : ""}{objectCount > 0 ? ` · ${objectCount} direct` : ""}</small>
      </header>
      {keyObjectNames.length > 0 && (
        <p className="region-summary" aria-label="Region summary">{keyObjectNames.join(" · ")}</p>
      )}
    </section>
  );
}

