test("trace corridor exposes an ordered entry-to-outcome main path", () => {
  for (const graph of Object.values(CANVAS_FIXTURES)) {
    for (const flow of graph.flows) {
      const corridor = deriveTraceCorridor(graph, flow.id);
      assert.ok(corridor.length >= 2, `${flow.id} must produce a main path`);
      assert.ok(corridor.every((step, index) => index === 0 || step.sequence >= corridor[index - 1].sequence), "Corridor steps must be ordered");
      const stepById = new Map(flow.steps.map((step) => [step.id, step]));
      for (const step of corridor) assert.ok(stepById.has(step.stepId), "Corridor steps must belong to the Flow");
      const transitions = corridor.slice(0, -1).map((step) => step.transitionRelationshipId).filter((id) => Boolean(id));
      for (const relationshipId of transitions) assert.ok(flow.relationshipIds.includes(relationshipId), "Corridor transitions must use declared Flow relationships");
      const entryRoles = corridor.filter((step) => step.transitionRole === "entry");
      const exitRoles = corridor.filter((step) => step.transitionRole === "exit");
      assert.equal(entryRoles.length, 1, "Corridor must mark exactly one entry transition");
      assert.equal(exitRoles.length, 1, "Corridor must mark exactly one exit transition");
      assert.equal(entryRoles[0].stepId, corridor[0].stepId);
    }
  }

  const view = deriveCanvasView(SMALL_CANVAS_FIXTURE, {
    mode: "trace",
    selection: { kind: "flow", id: SMALL_CANVAS_FIXTURE.flows[0].id },
    activeFlowId: SMALL_CANVAS_FIXTURE.flows[0].id,
    zoom: .9,
    searchQuery: "",
  });
  assert.equal(view.traceEntryObjectId, view.traceCorridor[0].objectId);
  assert.equal(view.traceExitObjectId, view.traceCorridor.at(-1).objectId);
});

