test("ELK compound layout is deterministic, non-overlapping and obstacle-safe", { timeout: 60_000 }, async () => {
  const durations = {};
  for (const [name, graph] of Object.entries(CANVAS_FIXTURES)) {
    const layout = await layoutSemanticGraph(graph);
    durations[name] = layout.durationMs;
    assert.equal(Object.keys(layout.objectRects).length, graph.objects.length, `${name} must lay out every Object`);
    assert.equal(Object.keys(layout.regionRects).length, graph.regions.length, `${name} must lay out every Region`);

    const rects = Object.values(layout.objectRects);
    for (let leftIndex = 0; leftIndex < rects.length; leftIndex += 1) {
      for (let rightIndex = leftIndex + 1; rightIndex < rects.length; rightIndex += 1) {
        assert.equal(overlap(rects[leftIndex], rects[rightIndex], 2), false, `${name}: Objects ${rects[leftIndex].id} and ${rects[rightIndex].id} overlap`);
      }
    }

    const regionById = new Map(graph.regions.map((region) => [region.id, region]));
    const objectById = new Map(graph.objects.map((object) => [object.id, object]));
    let routedCount = 0;
    for (const relationship of graph.relationships) {
      const sameRegion = objectById.get(relationship.sourceObjectId)?.regionId === objectById.get(relationship.targetObjectId)?.regionId;
      const route = layout.relationshipRoutes[relationship.id];
      if (!route) {
        assert.equal(sameRegion, false, `${name}: ${relationship.id} inside one Region must receive an ELK route`);
        continue;
      }
      routedCount += 1;
      assert.ok(route.points.length >= 2, `${name}: ${relationship.id} needs a usable route`);
      for (let pointIndex = 0; pointIndex < route.points.length - 1; pointIndex += 1) {
        const start = route.points[pointIndex];
        const end = route.points[pointIndex + 1];
        assert.ok(Math.abs(start.x - end.x) < .01 || Math.abs(start.y - end.y) < .01, `${name}: ${relationship.id} must be orthogonal`);
        for (const object of graph.objects) {
          if (object.id === relationship.sourceObjectId || object.id === relationship.targetObjectId) continue;
          assert.equal(segmentEntersRect(start, end, layout.objectRects[object.id]), false, `${name}: ${relationship.id} crosses ${object.id}`);
        }
      }
      if (route.labelPoint) {
        for (const object of graph.objects) {
          const rect = layout.objectRects[object.id];
          assert.equal(route.labelPoint.x > rect.x && route.labelPoint.x < rect.x + rect.width && route.labelPoint.y > rect.y && route.labelPoint.y < rect.y + rect.height, false, `${name}: ${relationship.id} label covers ${object.id}`);
        }
      }
    }
    assert.ok(routedCount > 0, `${name} must route intra-block Relationships with ELK`);

    const topLevelRects = Object.values(layout.regionRects).filter((rect) => rect.parentRegionId === undefined);
    assert.ok(topLevelRects.length >= 1, `${name} must expose top-level Region rects`);
    for (let leftIndex = 0; leftIndex < topLevelRects.length; leftIndex += 1) {
      for (let rightIndex = leftIndex + 1; rightIndex < topLevelRects.length; rightIndex += 1) {
        assert.equal(overlap(topLevelRects[leftIndex], topLevelRects[rightIndex]), false, `${name}: top-level Regions must not overlap`);
      }
    }
    void regionById;
  }
  assert.ok(durations.large < 15_000, `Large fixture layout should remain interactive, received ${durations.large}ms`);

  const first = await layoutSemanticGraph(MEDIUM_CANVAS_FIXTURE);
  const repeated = await layoutSemanticGraph(MEDIUM_CANVAS_FIXTURE, { previousLayout: first });
  assert.deepEqual(repeated.objectRects, first.objectRects, "Repeated graph opens must keep identical object placement");
  assert.deepEqual(repeated.relationshipRoutes, first.relationshipRoutes, "Repeated graph opens must keep identical routes");

  const extraObject = {
    ...MEDIUM_CANVAS_FIXTURE.objects[0],
    id: "medium:object:added",
    name: "New bounded service",
    layoutHints: { order: MEDIUM_CANVAS_FIXTURE.objects.length },
  };
  const extended = { ...MEDIUM_CANVAS_FIXTURE, id: "fixture:medium:extended", objects: [...MEDIUM_CANVAS_FIXTURE.objects, extraObject] };
  const extendedLayout = await layoutSemanticGraph(extended, { previousLayout: first });
  const stability = measureLayoutStability(first, extendedLayout);
  assert.ok(stability.relativeOrderRetention >= .9, `Minor additions must retain relative order, received ${stability.relativeOrderRetention}`);
});

test("top-level Regions compose two-dimensionally instead of one long band", { timeout: 60_000 }, async () => {
  for (const [name, graph] of Object.entries(CANVAS_FIXTURES)) {
    const layout = await layoutSemanticGraph(graph);
    const childRegionsByParent = new Map();
    for (const region of graph.regions) {
      const key = region.parentRegionId ?? null;
      childRegionsByParent.set(key, [...(childRegionsByParent.get(key) ?? []), region]);
    }
    const splitParent = graph.regions.find((region) => (childRegionsByParent.get(region.id)?.length ?? 0) >= 3)
      ?? (childRegionsByParent.get(null)?.length ?? 0) >= 3 ? null : null;
    const siblingIds = splitParent === null
      ? (childRegionsByParent.get(null) ?? (childRegionsByParent.get(graph.regions[0].id) ?? [])).map((region) => region.id)
      : (childRegionsByParent.get(splitParent) ?? []).map((region) => region.id);
    assert.ok(siblingIds.length >= 3, `${name} fixture must exercise a multi-sibling split level`);

    const siblingRects = siblingIds.map((id) => layout.regionRects[id]).filter(Boolean);
    const rows = new Set(siblingRects.map((rect) => Math.round(rect.y / 10)));
    assert.ok(rows.size >= 2, `${name}: sibling Regions must occupy more than one row (received ${rows.size})`);
    const width = Math.max(...siblingRects.map((rect) => rect.x + rect.width)) - Math.min(...siblingRects.map((rect) => rect.x));
    const height = Math.max(...siblingRects.map((rect) => rect.y + rect.height)) - Math.min(...siblingRects.map((rect) => rect.y));
    assert.ok(width / height <= 4.5, `${name}: composition aspect must stay near the viewport (received ${Math.round((width / height) * 10) / 10})`);
  }

  const packed = packRegionGrid([
    { id: "a", width: 900, height: 500 },
    { id: "b", width: 700, height: 620 },
    { id: "c", width: 800, height: 480 },
    { id: "d", width: 650, height: 700 },
  ]);
  assert.equal(packed.positions.size, 4);
  assert.ok(packed.width / packed.height <= 2, "Grid packing must prefer 2D composition over a single row");
  const repeated = packRegionGrid([
    { id: "a", width: 900, height: 500 },
    { id: "b", width: 700, height: 620 },
    { id: "c", width: 800, height: 480 },
    { id: "d", width: 650, height: 700 },
  ]);
  assert.deepEqual([...repeated.positions.entries()], [...packed.positions.entries()], "Grid packing must be deterministic");
});

test("default camera holds Architecture density with screen-space readability", async () => {
  assert.ok(DEFAULT_ZOOM_FLOOR >= READABILITY.objectMinScreenWidth / READABILITY.minObjectWorldWidth - 1e-9,
    "Default zoom floor must keep Object cards readable in screen space");
  for (const zoom of [DEFAULT_ZOOM_FLOOR, .6, .35]) {
    const level = zoom >= .48 && zoom < .8 ? "architecture" : zoom < .48 ? "landscape" : "component";
    const effectiveLabel = READABILITY.objectLabelPx * zoom * objectLabelScale(zoom, level);
    assert.ok(effectiveLabel >= READABILITY.labelScreenFloor - .01, `Object labels must stay >= ${READABILITY.labelScreenFloor}px on screen at zoom ${zoom} (received ${Math.round(effectiveLabel * 100) / 100})`);
    const effectiveRegionHeader = READABILITY.regionHeaderPx * zoom * regionLabelScale(zoom);
    assert.ok(effectiveRegionHeader >= READABILITY.labelScreenFloor - .01, `Region headers must stay >= ${READABILITY.labelScreenFloor}px on screen at zoom ${zoom} (received ${Math.round(effectiveRegionHeader * 100) / 100})`);
  }

  const layout = await layoutSemanticGraph(MEDIUM_CANVAS_FIXTURE);
  const frame = frameTopRegions(layout);
  assert.ok(frame.nodes.length >= 1, "Initial framing must target top-level Regions");
  assert.equal(frame.minZoom, DEFAULT_ZOOM_FLOOR, "Initial framing may not fall below the Architecture density floor");
  assert.ok(!frame.nodes.some((node) => node.id.includes(":object:")), "Initial framing must target Regions, not every Object");

  assert.equal(dockViewportShift({ left: 0, right: 0 }, { left: 0, right: 336 }), -168, "Right dock opening shifts content left by half the dock");
  assert.equal(dockViewportShift({ left: 0, right: 336 }, { left: 0, right: 0 }), 168, "Right dock closing shifts content right by half the dock");
  assert.equal(dockViewportShift({ left: 0, right: 0 }, { left: 316, right: 0 }), 158, "Left dock opening shifts content right by half the dock");
});

test("Region nodes carry a readable subtree summary", { timeout: 60_000 }, async () => {
  const graph = MEDIUM_CANVAS_FIXTURE;
  const layout = await layoutSemanticGraph(graph);
  const view = deriveCanvasView(graph, { mode: "browse", selection: null, activeFlowId: null, zoom: DEFAULT_ZOOM_FLOOR, searchQuery: "" });
  const { nodes } = projectSemanticGraph(graph, layout, view);
  const regionNodes = nodes.filter((node) => node.type === "region");
  assert.ok(regionNodes.length > 0);
  const objectNames = new Set(graph.objects.map((object) => object.name));
  for (const node of regionNodes) {
    const data = node.data;
    assert.ok(data.subtreeObjectCount >= data.objectCount, "Subtree count must include nested Regions");
    assert.ok(data.keyObjectNames.length <= 3, "Region summary must stay compact");
    for (const name of data.keyObjectNames) assert.ok(objectNames.has(name), "Key objects must name real subtree members");
  }
  const root = regionNodes.reduce((best, node) => (node.data.subtreeObjectCount > best.data.subtreeObjectCount ? node : best));
  assert.equal(root.data.subtreeObjectCount, graph.objects.length, "Root Region summary must account for every Object");
});

