import { MarkerType, type Edge, type Node } from "@xyflow/react";
import { visibleObjectIds, type CanvasViewModel } from "./interaction";
import type { CanvasLayout } from "./layout";
import { indexSemanticGraph, type SemanticGraph } from "./semantic-graph";
import type { ObjectNodeData, RegionNodeData, RelationshipEdgeData } from "./types";

export type CanvasObjectNode = Node<ObjectNodeData, "object">;
export type CanvasRegionNode = Node<RegionNodeData, "region">;
export type CanvasNode = CanvasObjectNode | CanvasRegionNode;
export type CanvasRelationshipEdge = Edge<RelationshipEdgeData, "relationship">;

function handleId(side: "left" | "right" | "top" | "bottom", role: "source" | "target") {
  return `${role}-${side}`;
}

function subtreeObjectIds(graph: SemanticGraph, regionId: string): string[] {
  const index = indexSemanticGraph(graph);
  const direct = (index.objectsByRegionId.get(regionId) ?? []).map((object) => object.id);
  const nested = (index.childRegionsByRegionId.get(regionId) ?? []).flatMap((child) => subtreeObjectIds(graph, child.id));
  return [...direct, ...nested];
}

export function projectSemanticGraph(
  graph: SemanticGraph,
  layout: CanvasLayout,
  view: CanvasViewModel,
): { nodes: CanvasNode[]; edges: CanvasRelationshipEdge[] } {
  const index = indexSemanticGraph(graph);
  const visibleIds = visibleObjectIds(graph, view);
  const activeFlow = view.activeFlowId ? index.flowById.get(view.activeFlowId) : undefined;
  const corridorByRelationshipId = new Map(
    view.traceCorridor.map((step) => step.transitionRelationshipId ? [step.transitionRelationshipId, step] : []).filter((entry) => entry.length > 0),
  );
  const regionNodes = graph.regions
    .map<CanvasRegionNode | null>((region) => {
      const rect = layout.regionRects[region.id];
      if (!rect) return null;
      const subtreeIds = subtreeObjectIds(graph, region.id);
      const subtreeObjects = subtreeIds
        .map((id) => index.objectById.get(id))
        .filter((object): object is NonNullable<typeof object> => Boolean(object));
      const keyObjectNames = [...subtreeObjects]
        .sort((left, right) => right.importance.score - left.importance.score
          || ((index.incomingByObjectId.get(right.id)?.length ?? 0) + (index.outgoingByObjectId.get(right.id)?.length ?? 0))
            - ((index.incomingByObjectId.get(left.id)?.length ?? 0) + (index.outgoingByObjectId.get(left.id)?.length ?? 0))
          || left.id.localeCompare(right.id))
        .slice(0, 3)
        .map((object) => object.name);
      return {
        id: region.id,
        type: "region",
        position: { x: rect.x, y: rect.y },
        data: {
          region,
          emphasis: view.regionEmphasis.get(region.id) ?? "normal",
          zoomLevel: view.zoomLevel,
          zoom: view.zoom,
          objectCount: index.objectsByRegionId.get(region.id)?.length ?? 0,
          childRegionCount: index.childRegionsByRegionId.get(region.id)?.length ?? 0,
          subtreeObjectCount: subtreeIds.length,
          keyObjectNames,
          depth: rect.depth,
        },
        draggable: false,
        selectable: false,
        focusable: false,
        zIndex: 0,
        style: { width: rect.width, height: rect.height },
      };
    })
    .filter((node): node is CanvasRegionNode => Boolean(node));

  const objectNodes = graph.objects
    .filter((object) => visibleIds.has(object.id))
    .map<CanvasObjectNode | null>((object) => {
      const rect = layout.objectRects[object.id];
      if (!rect) return null;
      const traceRole = view.traceEntryObjectId === object.id
        ? "entry" as const
        : view.traceExitObjectId === object.id
          ? "exit" as const
          : undefined;
      return {
        id: object.id,
        type: "object",
        position: { x: rect.x, y: rect.y },
        data: {
          object,
          emphasis: view.objectEmphasis.get(object.id) ?? "normal",
          zoomLevel: view.zoomLevel,
          zoom: view.zoom,
          incomingCount: index.incomingByObjectId.get(object.id)?.length ?? 0,
          outgoingCount: index.outgoingByObjectId.get(object.id)?.length ?? 0,
          flowSteps: (activeFlow?.steps ?? [])
            .filter((step) => step.objectId === object.id)
            .map((step) => ({ sequence: step.sequence, role: step.role, title: step.title })),
          traceRole,
        },
        draggable: true,
        selectable: true,
        selected: view.selection?.kind === "object" && view.selection.id === object.id,
        zIndex: view.objectEmphasis.get(object.id) === "primary" ? 30 : 10,
        style: { width: rect.width, height: rect.height },
      };
    })
    .filter((node): node is CanvasObjectNode => Boolean(node));

  const edges = graph.relationships
    .filter((relationship) => visibleIds.has(relationship.sourceObjectId) && visibleIds.has(relationship.targetObjectId))
    .map<CanvasRelationshipEdge>((relationship) => {
    const route = layout.relationshipRoutes[relationship.id];
    const emphasis = view.relationshipEmphasis.get(relationship.id) ?? "normal";
    const corridorStep = view.mode === "trace" ? corridorByRelationshipId.get(relationship.id) : undefined;
    const renderedRoute = view.mode === "trace" && corridorStep ? undefined : route;
    const markerColor = emphasis === "active"
      ? "#e8f4ee"
      : emphasis === "suppressed"
        ? "#243137"
        : emphasis === "muted"
